import React, { useContext, useEffect, useState } from 'react';
import { Container, Card, Form, Row, Col, Alert, Button, Spinner } from 'react-bootstrap';
import { useLocation, useNavigate } from 'react-router-dom';
import { FaBookOpen, FaImage, FaDownload, FaExclamationCircle, FaEdit, FaTrash } from 'react-icons/fa';
import Layout from '../common/Layout';
import { AuthContext } from '../../App';
import {
  fetchInstituteNames,
  fetchBranchNames,
  fetchAcademicYears,
  fetchBranchClasses,
  fetchClassSections,
  fetchClassSubjects,
  uploadHomeworkImage,
  createHomeworkUpload,
  fetchHomeWorkUploads,
  updateHomeworkUpload,
  deleteHomeworkUpload,
} from '../../services/HomeworkServices/homeworkServices';

function HomeworkPage() {
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const navigate = useNavigate();
  const location = useLocation();
  const homeworkToEdit = location.state?.homeworkToEdit;

  const [institutes, setInstitutes] = useState([]);
  const [branches, setBranches] = useState([]);
  const [academicYears, setAcademicYears] = useState([]);
  const [classesList, setClassesList] = useState([]);
  const [sections, setSections] = useState([]);
  const [subjects, setSubjects] = useState([]);

  const [instituteId, setInstituteId] = useState('');
  const [branchId, setBranchId] = useState('');
  const [academicYear, setAcademicYear] = useState('');
  const [classId, setClassId] = useState('');
  const [sectionId, setSectionId] = useState('');
  const [subjectId, setSubjectId] = useState('');
  const [description, setDescription] = useState('');
  const [imageUrl, setImageUrl] = useState('');

  const [uploading, setUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isFetching, setIsFetching] = useState(false);
  const [homeworkList, setHomeworkList] = useState([]);
  const [fetchError, setFetchError] = useState('');
  const [editingId, setEditingId] = useState('');
  const [editDesc, setEditDesc] = useState('');
  const [editSubjectId, setEditSubjectId] = useState('');
  const [isUpdating, setIsUpdating] = useState(false);
  const [deletingId, setDeletingId] = useState('');
  const [alertShow, setAlertShow] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');
  const [alertVarient, setAlertVarient] = useState('');
  const [fetchedAlertShow, setFetchedAlertShow] = useState(false);
  const [fetchedAlertMessage, setFetchedAlertMessage] = useState('');
  const [fetchedAlertVarient, setFetchedAlertVarient] = useState('');

  useEffect(() => {
    if (user.instid && user.instnm) {
      setInstitutes([{ instid: user.instid, instnm: user.instnm }]);
      setInstituteId(String(user.instid));
    }
    if (user.brcid && user.brcnm) {
      setBranches([{ brcid: user.brcid, brcnm: user.brcnm }]);
      setBranchId(String(user.brcid));
    }
    if (user.acdmcyr) {
      setAcademicYears([{ yrid: user.acdmcyr, yrnm: user.acdmcyr }]);
      setAcademicYear(String(user.acdmcyr));
    }
    if (user.clsid) {
      setClassId(String(user.clsid));
    }
    if (user.secid) {
      setSectionId(String(user.secid));
    }

    // Load full lists in the background
    loadInstitutes();
    loadAcademicYears();

    if (user.instid) {
      loadBranches(user.instid);
    }
    if (user.brcid && user.acdmcyr) {
      loadClasses(user.brcid, user.acdmcyr);
    }
    if (user.clsid) {
      loadClassDetails(user.clsid);
    }
  }, [user.instid, user.instnm, user.brcid, user.brcnm, user.acdmcyr, user.clsid, user.secid]);

  useEffect(() => {
    fetchHomeworkData();
  }, [user.instid, user.brcid, user.clsid, user.secid, user.stfid, user.typ]);

  useEffect(() => {
    if (!homeworkToEdit) return;

    setInstituteId(String(homeworkToEdit.fkinstid || ''));
    setBranchId(String(homeworkToEdit.fkbrcid || ''));
    setAcademicYear(String(homeworkToEdit.acdmcyr || user.acdmcyr || ''));
    setClassId(String(homeworkToEdit.fkclsid || ''));
    setSectionId(String(homeworkToEdit.fksecid || ''));
    setSubjectId(String(homeworkToEdit.fksubid || ''));
    setDescription(homeworkToEdit.desc || '');
    setImageUrl(homeworkToEdit.imguid || homeworkToEdit.imguld || '');

    if (homeworkToEdit.fkinstid) loadBranches(homeworkToEdit.fkinstid);
    if (homeworkToEdit.fkbrcid) {
      loadClasses(homeworkToEdit.fkbrcid, homeworkToEdit.acdmcyr || user.acdmcyr);
    }
    if (homeworkToEdit.fkclsid) loadClassDetails(homeworkToEdit.fkclsid);
  }, [homeworkToEdit]);

  const fetchHomeworkData = async () => {
    setIsFetching(true);
    setFetchError('');
    const params = {
      typ: user.typ,
      instid: user.instid,
      brcid: user.brcid,
      clsid: user.clsid,
      secid: user.secid,
      stfid: user.stfid,
      acdmcyr: user.acdmcyr,
      usrid: user.usrid,
    };
    const res = await fetchHomeWorkUploads(params);
    setIsFetching(false);
    if (res && res.status === 'success') {
      setHomeworkList(res.payload || []);
    } else {
      setFetchError(res?.error?.message || 'Failed to Fetch Home Work');
    }
  };

  const startEdit = (hw) => {
    navigate('/homework', { state: { homeworkToEdit: hw } });
  };

  const cancelEdit = () => {
    setEditingId('');
    setEditDesc('');
    setEditSubjectId('');
  };

  const handleUpdate = async (hw) => {
    if (!editDesc) {
      setFetchedAlert('Please Enter Description');
      return;
    }
    setIsUpdating(true);
    const payload = {
      hmwkudid: hw.hmwkudid,
      fkinstid: hw.fkinstid,
      fkbrcid: hw.fkbrcid,
      desc: editDesc,
      fkclsid: hw.fkclsid,
      fksubid: editSubjectId,
      fksecid: hw.fksecid,
      imguid: hw.imguid || hw.imguld || '',
      acdmcyr: hw.acdmcyr || user.acdmcyr,
      updby: user.usrid,
    };
    const res = await updateHomeworkUpload(payload);
    setIsUpdating(false);
    if (res && res.status === 'success') {
      setFetchedAlert('Home Work Updated Successfully', 'success');
      cancelEdit();
      fetchHomeworkData();
    } else {
      setFetchedAlert(res?.error?.message || 'Failed to Update Home Work');
    }
  };

  const handleDelete = async (hmwkudid) => {
    if (!window.confirm('Are you sure you want to delete this Home Work?')) return;
    setDeletingId(hmwkudid);
    const res = await deleteHomeworkUpload({ hmwkudid });
    setDeletingId('');
    if (res && res.status === 'success') {
      setFetchedAlert('Home Work Deleted Successfully', 'success');
      fetchHomeworkData();
    } else {
      setFetchedAlert(res?.error?.message || 'Failed to Delete Home Work');
    }
  };

  const setFetchedAlert = (message, varient = 'danger') => {
    setFetchedAlertMessage(message);
    setFetchedAlertVarient(varient);
    setFetchedAlertShow(true);
    setTimeout(() => {
      setFetchedAlertShow(false);
      setFetchedAlertMessage('');
      setFetchedAlertVarient('');
    }, 5000);
  };

  const loadInstitutes = async () => {
    const res = await fetchInstituteNames({});
    if (res?.status === 'success' && res.payload) {
      setInstitutes(res.payload);
    }
  };

  const loadAcademicYears = async () => {
    const res = await fetchAcademicYears({});
    if (res?.status === 'success' && res.payload) {
      setAcademicYears(res.payload);
    }
  };

  const loadBranches = async (instId) => {
    const res = await fetchBranchNames({ instid: instId });
    if (res?.status === 'success' && res.payload) {
      setBranches(res.payload);
    }
  };

  const loadClasses = async (brcId, acdmCyr) => {
    if (!acdmCyr) return;
    const res = await fetchBranchClasses({ brcid: brcId, acdmcyr: acdmCyr });
    if (res?.status === 'success' && res.payload) {
      setClassesList(res.payload);
    }
  };

  const handleInstituteChange = async (e) => {
    const val = e.target.value;
    setInstituteId(val);
    setBranchId('');
    setClassId('');
    setSectionId('');
    setSubjectId('');
    setBranches([]);
    setClassesList([]);
    setSections([]);
    setSubjects([]);
    if (val) {
      loadBranches(val);
    }
  };

  const handleBranchChange = async (e) => {
    const val = e.target.value;
    setBranchId(val);
    setClassId('');
    setSectionId('');
    setSubjectId('');
    setClassesList([]);
    setSections([]);
    setSubjects([]);
    if (val) {
      loadClasses(val, academicYear);
    }
  };

  const loadClassDetails = async (clsId) => {
    const [resSec, resSub] = await Promise.all([
      fetchClassSections({ clsid: clsId }),
      fetchClassSubjects({ clsid: clsId }),
    ]);
    if (resSec?.status === 'success' && resSec.payload) {
      setSections(resSec.payload);
    }
    if (resSub?.status === 'success' && resSub.payload) {
      setSubjects(resSub.payload);
    }
  };

  const handleClassChange = async (e) => {
    const val = e.target.value;
    setClassId(val);
    setSectionId('');
    setSubjectId('');
    setSections([]);
    setSubjects([]);
    if (val) {
      loadClassDetails(val);
    }
  };

  const hideMessage = () => {
    setTimeout(() => {
      setAlertShow(false);
      setAlertMessage('');
      setAlertVarient('');
    }, 5000);
  };

  const handleImageChange = async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setUploading(true);
    const newFile = new File([file], file.name, {
      type: file.type,
      lastModified: file.lastModified,
    });
    const formData = new FormData();
    formData.append('image', newFile);
    formData.append('type', 'homework');
    formData.append('imgtyp', 'student_photo');
    const res = await uploadHomeworkImage(formData);
    setUploading(false);
    if (res && res.status === 'success' && res.payload && res.payload.url) {
      setImageUrl(res.payload.url);
      setAlertMessage('Image Uploaded Successfully');
      setAlertVarient('success');
      setAlertShow(true);
      hideMessage();
    } else {
      setAlertMessage('Failed to Upload the Image');
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
    }
  };

  const handleSubmit = async () => {
    if (!instituteId || !branchId || !academicYear || !classId || !sectionId || !subjectId || !description) {
      setAlertMessage('Please fill all required fields');
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
      return;
    }
    const homeworkImageUrl = imageUrl.trim();
    if (!homeworkImageUrl) {
      setAlertMessage('Please upload an image or enter an Image URL');
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
      return;
    }
    setIsSaving(true);
    const payload = {
      fkinstid: instituteId,
      fkbrcid: branchId,
      desc: description,
      fkclsid: classId,
      fksubid: subjectId,
      fksecid: sectionId,
      stfid: user.stfid || '',
      imguid: homeworkImageUrl,
      acdmcyr: academicYear,
      usrid: user.usrid,
    };
    const res = homeworkToEdit
      ? await updateHomeworkUpload({
          ...payload,
          hmwkudid: homeworkToEdit.hmwkudid,
          updby: user.usrid,
        })
      : await createHomeworkUpload(payload);
    setIsSaving(false);
    if (res && res.status === 'success') {
      setAlertMessage(homeworkToEdit ? 'Home Work Updated Successfully' : 'Home Work Upload Created Successfully');
      setAlertVarient('success');
      setAlertShow(true);
      hideMessage();
      // Reset form
      setInstituteId('');
      setBranchId('');
      setAcademicYear('');
      setClassId('');
      setSectionId('');
      setSubjectId('');
      setDescription('');
      setImageUrl('');
      setBranches([]);
      setClassesList([]);
      setSections([]);
      setSubjects([]);
      if (homeworkToEdit) {
        navigate('/homework', { replace: true });
      }
    } else {
      setAlertMessage(res?.error?.message || `Failed to ${homeworkToEdit ? 'Update' : 'Upload'} Home Work`);
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
    }
  };

  return (
    <Layout>
      <Container className="py-4">
        <button
          className="btn btn-sm btn-light mb-3"
          onClick={() => navigate('/dashboard')}
        >
          ← Back to Dashboard
        </button>
        <Card className="shadow-sm">
          <Card.Header className="bg-primary text-white d-flex justify-content-between align-items-center">
            <h5 className="mb-0 d-flex align-items-center gap-2">
              <FaBookOpen /> {homeworkToEdit ? 'Update Home Work' : 'Home Work Upload'}
            </h5>
          </Card.Header>
          <Card.Body>
            <Alert
              variant={alertVarient}
              show={alertShow}
              onClose={() => setAlertShow(false)}
              dismissible
            >
              {alertMessage}
            </Alert>

            <Form>
              <Row>
                <Col md={6}>
                  <Form.Group className="mb-3">
                    <Form.Label>Institute <span className="text-danger">*</span></Form.Label>
                    <Form.Select value={instituteId} onChange={handleInstituteChange}>
                      <option value="">Select Institute</option>
                      {institutes.map((inst) => (
                        <option key={inst.instid} value={inst.instid}>
                          {inst.instnm}
                        </option>
                      ))}
                    </Form.Select>
                  </Form.Group>
                </Col>
                <Col md={6}>
                  <Form.Group className="mb-3">
                    <Form.Label>Branch <span className="text-danger">*</span></Form.Label>
                    <Form.Select value={branchId} onChange={handleBranchChange} disabled={!instituteId}>
                      <option value="">Select Branch</option>
                      {branches.map((br) => (
                        <option key={br.brcid} value={br.brcid}>
                          {br.brcnm}
                        </option>
                      ))}
                    </Form.Select>
                  </Form.Group>
                </Col>
                <Col md={6}>
                  <Form.Group className="mb-3">
                    <Form.Label>Academic Year <span className="text-danger">*</span></Form.Label>
                    <Form.Select value={academicYear} onChange={(e) => setAcademicYear(e.target.value)}>
                      <option value="">Select Academic Year</option>
                      {academicYears.map((yr) => (
                        <option key={yr.yrid} value={yr.yrnm}>
                          {yr.yrnm}
                        </option>
                      ))}
                    </Form.Select>
                  </Form.Group>
                </Col>
                <Col md={6}>
                  <Form.Group className="mb-3">
                    <Form.Label>Class <span className="text-danger">*</span></Form.Label>
                    <Form.Select value={classId} onChange={handleClassChange} disabled={!branchId}>
                      <option value="">Select Class</option>
                      {classesList.map((c) => (
                        <option key={c.clsid} value={c.clsid}>
                          {c.clsnm}
                        </option>
                      ))}
                    </Form.Select>
                  </Form.Group>
                </Col>
                <Col md={6}>
                  <Form.Group className="mb-3">
                    <Form.Label>Section <span className="text-danger">*</span></Form.Label>
                    <Form.Select value={sectionId} onChange={(e) => setSectionId(e.target.value)} disabled={!classId}>
                      <option value="">Select Section</option>
                      {sections.map((sec) => (
                        <option key={sec.secid} value={sec.secid}>
                          {sec.secnm}
                        </option>
                      ))}
                    </Form.Select>
                  </Form.Group>
                </Col>
                <Col md={6}>
                  <Form.Group className="mb-3">
                    <Form.Label>Subject <span className="text-danger">*</span></Form.Label>
                    <Form.Select value={subjectId} onChange={(e) => setSubjectId(e.target.value)} disabled={!classId}>
                      <option value="">Select Subject</option>
                      {subjects.map((s) => (
                        <option key={s.subid} value={s.subid}>
                          {s.subnm}
                        </option>
                      ))}
                    </Form.Select>
                  </Form.Group>
                </Col>
              </Row>

              <Form.Group className="mb-3 mt-2">
                <Form.Label>Description <span className="text-danger">*</span></Form.Label>
                <Form.Control
                  as="textarea"
                  rows={3}
                  placeholder="Enter home work description..."
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
              </Form.Group>

              <Form.Group className="mb-3">
                <Form.Label>
                  <FaImage className="me-1" /> Image Upload
                </Form.Label>
                <Form.Control
                  type="file"
                  accept=".png,.jpg,.jpeg,.bmp,.pdf"
                  onChange={handleImageChange}
                />
                <Form.Text className="text-muted">
                  {uploading ? 'Uploading The Image...' : ''}
                </Form.Text>
              </Form.Group>

              <Form.Group className="mb-3">
                <Form.Label>Image URL <span className="text-danger">*</span></Form.Label>
                <Form.Control
                  type="url"
                  placeholder="https://example.com/homework-image.jpg"
                  value={imageUrl}
                  onChange={(e) => setImageUrl(e.target.value.trim())}
                  disabled={uploading}
                />
                <Form.Text className="text-muted">
                  Upload a file above or paste an image/PDF URL. The URL is saved with the homework.
                </Form.Text>
              </Form.Group>

              {imageUrl && (
                <div className="hw-image-preview mb-3">
                  {imageUrl.toLowerCase().endsWith('.pdf') ? (
                    <a href={imageUrl} target="_blank" rel="noreferrer">
                      View PDF
                    </a>
                  ) : (
                    <img src={imageUrl} alt="homework" width="120" className="rounded border" />
                  )}
                </div>
              )}

              <div className="d-flex justify-content-end mt-4">
                <Button variant="secondary" className="me-2" onClick={() => navigate(homeworkToEdit ? '/homework' : '/dashboard')}>
                  Cancel
                </Button>
                <Button variant="primary" onClick={handleSubmit} disabled={isSaving || uploading}>
                  {isSaving ? (
                    <>
                      <Spinner as="span" animation="border" size="sm" role="status" aria-hidden="true" className="me-2" />
                      Uploading...
                    </>
                  ) : (
                    homeworkToEdit ? 'Update' : 'Submit'
                  )}
                </Button>
              </div>
            </Form>
          </Card.Body>
        </Card>

        {/* ── Fetched Home Work (bottom) ── */}
        <Card className="shadow-sm mt-4">
          <Card.Header className="bg-success text-white d-flex justify-content-between align-items-center">
            <h5 className="mb-0 d-flex align-items-center gap-2">
              <FaBookOpen />Home Work
            </h5>
            <div className="d-flex align-items-center gap-2">
              {/* {!isFetching && (
                <span className="badge bg-light text-dark">
                  {homeworkList.length} found
                </span>
              )} */}
              <Button
                variant="light"
                size="sm"
                className="text-success fw-semibold"
                onClick={fetchHomeworkData}
                disabled={isFetching}
              >
                {isFetching ? (
                  <>
                    <Spinner as="span" animation="border" size="sm" role="status" aria-hidden="true" className="me-2" />
                    Fetching...
                  </>
                ) : (
                  'Fetch'
                )}
              </Button>
            </div>
          </Card.Header>
          <Card.Body>
            {fetchError && (
              <Alert variant="danger" className="mb-3">
                <FaExclamationCircle className="me-1" /> {fetchError}
              </Alert>
            )}
            {fetchedAlertShow && (
              <Alert
                variant={fetchedAlertVarient}
                className="mb-3"
                onClose={() => setFetchedAlertShow(false)}
                dismissible
              >
                {fetchedAlertMessage}
              </Alert>
            )}
            {isFetching && homeworkList.length === 0 && (
              <div className="text-center text-muted py-4">
                <Spinner as="span" animation="border" role="status" className="mb-2" />
                <div>Fetching Home Work...</div>
              </div>
            )}
            {!isFetching && homeworkList.length === 0 && !fetchError && (
              <p className="text-muted text-center mb-0 py-3">No Home Work found.</p>
            )}
            {homeworkList.length > 0 && (
              <div className="hw-fetch-list">
                {homeworkList.map((hw) => (
                  <div className="hw-fetch-item" key={hw.hmwkudid}>
                    <div className="hw-fetch-item-head">
                      <div>
                        <strong>{hw.sbnm || 'Subject'}</strong>
                        <span className="hw-fetch-date ms-2">
                          {hw.crtdt ? new Date(hw.crtdt).toLocaleDateString() : ''}
                        </span>
                      </div>
                      {editingId !== hw.hmwkudid && (
                        <div className="hw-fetch-actions">
                          <button
                            className="hw-action-btn hw-action-edit"
                            title="Update"
                            onClick={() => startEdit(hw)}
                          >
                            <FaEdit />
                          </button>
                          <button
                            className="hw-action-btn hw-action-delete"
                            title="Delete"
                            disabled={deletingId === hw.hmwkudid}
                            onClick={() => handleDelete(hw.hmwkudid)}
                          >
                            {deletingId === hw.hmwkudid ? (
                              <Spinner as="span" animation="border" size="sm" />
                            ) : (
                              <FaTrash />
                            )}
                          </button>
                        </div>
                      )}
                    </div>

                    {editingId === hw.hmwkudid ? (
                      <div className="hw-edit-form mt-2">
                        <Form.Group className="mb-2">
                          <Form.Label>Subject</Form.Label>
                          <Form.Select
                            value={editSubjectId}
                            onChange={(e) => setEditSubjectId(e.target.value)}
                          >
                            <option value="">Select Subject</option>
                            {subjects.map((s) => (
                              <option key={s.subid} value={s.subid}>
                                {s.subnm}
                              </option>
                            ))}
                          </Form.Select>
                        </Form.Group>
                        <Form.Group className="mb-2">
                          <Form.Label>Description</Form.Label>
                          <Form.Control
                            as="textarea"
                            rows={2}
                            value={editDesc}
                            onChange={(e) => setEditDesc(e.target.value)}
                          />
                        </Form.Group>
                        <div className="d-flex gap-2">
                          <Button
                            variant="success"
                            size="sm"
                            onClick={() => handleUpdate(hw)}
                            disabled={isUpdating}
                          >
                            {isUpdating ? 'Saving...' : 'Save'}
                          </Button>
                          <Button variant="secondary" size="sm" onClick={cancelEdit}>
                            Cancel
                          </Button>
                        </div>
                      </div>
                    ) : (
                      <>
                        <p className="hw-fetch-desc mb-1">{hw.desc}</p>
                        <div className="hw-fetch-meta">
                          {hw.clsnm && <span className="badge bg-light text-dark me-1">{hw.clsnm}</span>}
                          {hw.senm && <span className="badge bg-light text-dark me-1">{hw.senm}</span>}
                        </div>
                        {(hw.imguid || hw.imguld) && (
                          <div className="mt-2">
                            {(hw.imguid || hw.imguld).toLowerCase().endsWith('.pdf') ? (
                              <a href={hw.imguid || hw.imguld} target="_blank" rel="noreferrer" className="btn btn-sm btn-outline-primary">
                                <FaDownload className="me-1" /> View PDF
                              </a>
                            ) : (
                              <img src={hw.imguid || hw.imguld} alt="homework" width="90" className="rounded border" />
                            )}
                          </div>
                        )}
                      </>
                    )}
                  </div>
                ))}
              </div>
            )}
          </Card.Body>
        </Card>
      </Container>
    </Layout>
  );
}

export default HomeworkPage;
